def cycle_sort(arr):
    writes = 0

    for cycleStart in range(0, len(arr) - 1):
        item = arr[cycleStart]
        pos = cycleStart

        # Find where to put the item.
        for i in range(cycleStart + 1, len(arr)):
            if arr[i] < item:
                pos += 1

        if pos == cycleStart:
            continue

        while item == arr[pos]:
            pos += 1

        arr[pos], item = item, arr[pos]
        writes += 1

        while pos != cycleStart:
            pos = cycleStart
            for i in range(cycleStart + 1, len(arr)):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1

            arr[pos], item = item, arr[pos]
            writes += 1

    return arr

def isMatch(s: str, p: str) -> bool:
    """
    Returns True if the input string `s` matches the pattern `p`.
    The pattern `p` can include '.' which matches any single character
    and '*' which matches zero or more of the preceding element.
    """
    # Use dynamic programming to solve the problem
    m, n = len(s), len(p)

    # dp[i][j] means whether s[0:i] matches p[0:j]
    dp = [[False] * (n + 1) for _ in range(m + 1)]

    # Both s and p are empty
    dp[0][0] = True

    # Handle patterns with *
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2] # Matches zero preceding element (e.g. x*)

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2]
                if p[j - 2] == '.' or p[j - 2] == s[i - 1]:
                    dp[i][j] = dp[i][j] or dp[i - 1][j]

    return dp[m][n]

def rabin_karp_enhanced(pattern: str, text: str) -> int:
    """
    Finds the first occurrence of the pattern in the text using the Rabin-Karp algorithm.
    :param pattern: The substring to be searched.
    :param text: The text within which the pattern is to be searched.
    :return: The starting index of the first occurrence of the pattern in the text, or -1 if the pattern is not found.
    """
    if len(pattern) > len(text):
        return -1

    base = 256  # Number of characters in the input alphabet
    prime = 101  # A prime number to use for hashing

    pattern_length = len(pattern)
    text_length = len(text)

    pattern_hash = 0
    text_hash = 0
    h = 1

    for i in range(pattern_length - 1):
        h = (h * base) % prime

    for i in range(pattern_length):
        pattern_hash = (base * pattern_hash + ord(pattern[i])) % prime
        text_hash = (base * text_hash + ord(text[i])) % prime

    for i in range(text_length - pattern_length + 1):
        if pattern_hash == text_hash:
            if text[i:i + pattern_length] == pattern:
                return i

        if i < text_length - pattern_length:
            text_hash = (base * (text_hash - ord(text[i]) * h) + ord(text[i + pattern_length])) % prime

            if text_hash < 0:
                text_hash += prime

    return -1

