def smallest_subsequence(s):
    """
    Returns the smallest subsequence that contains all the unique characters in `s`.
    This subsequence will maintain the order of the first occurrence of each character.
    """
    stack = []
    seen = set()
    last_occurrence = {ch: i for i, ch in enumerate(s)}

    for i, ch in enumerate(s):
        if ch not in seen:
            while stack and ch < stack[-1] and i < last_occurrence[stack[-1]]:
                seen.remove(stack.pop())
            seen.add(ch)
            stack.append(ch)

    return ''.join(stack)

def count_pairs_with_sum(numbers, target_sum):
    """
    Returns the count of distinct pairs in the list 'numbers' whose sum equals 'target_sum'.
    """
    seen = set()
    pairs = set()

    for number in numbers:
        complement = target_sum - number
        if complement in seen:
            pairs.add(tuple(sorted((number, complement))))
        seen.add(number)

