import heapq

def rearrangeString(s, k):
    if k == 0:
        return s

    counter = Counter(s)
    max_heap = [(-value, key) for key, value in counter.items()]
    heapq.heapify(max_heap)

    rearranged = []
    wait_queue = []

    while max_heap:
        count, char = heapq.heappop(max_heap)
        rearranged.append(char)

        wait_queue.append((count + 1, char))

        if len(wait_queue) >= k:
            released = wait_queue.pop(0)
            if released[0] < 0:
                heapq.heappush(max_heap, released)

    if len(rearranged) != len(s):
        return ""

    return "".join(rearranged)

