def unique_paths_with_obstacles(grid):
    """
    Calculate the number of unique paths from the top-left corner to the bottom-right corner
    in a grid with obstacles. 0 represents an empty cell and 1 represents an obstacle.

    :param grid: List[List[int]] - 2D grid
    :return: int - number of unique paths or -1 if no path exists
    """
    if not grid or not grid[0] or grid[0][0] == 1:
        return -1

    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]

    # Starting point
    dp[0][0] = 1

    # Fill the first row
    for j in range(1, n):
        dp[0][j] = dp[0][j - 1] if grid[0][j] == 0 else 0

    # Fill the first column
    for i in range(1, m):
        dp[i][0] = dp[i - 1][0] if grid[i][0] == 0 else 0

    # Fill the rest of dp table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
            else:
                dp[i][j] = 0

    # If the destination is an obstacle
    if dp[-1][-1] == 0:
        return -1

    return dp[-1][-1]

def shortest_palindrome(s):
    """
    Generates the shortest possible palindrome by appending characters to the end of the string s.
    """
    if s == s[::-1]:
        return s  # if the string is already a palindrome

    for i in range(len(s)):
        if s[i:] == s[i:][::-1]:
            return s + s[:i][::-1]

    return s + s[:-1][::-1]

def max_subarray_sum(arr):
    """
    Returns the maximum subarray sum in the given array using Kadane's algorithm.
    """
    if not arr:
        return 0

    max_current = max_global = arr[0]

    for i in range(1, len(arr)):
        max_current = max(arr[i], max_current + arr[i])
        if max_current > max_global:
