def split_path(path: str) -> tuple:
    """
    Splits the given path into directory and file components.

    Parameters:
    path (str): The path to be split.

    Returns:
    tuple: A tuple containing the directory part and the file part.
    """
    if path == '':
        return ('', '')

    # Find the last occurrence of '/'
    index = path.rfind('/')

    if index == -1:
        # No '/' in the path
        return ('', path)
    elif index == len(path) - 1:
        # The path ends with a '/'
        return (path.rstrip('/'), '')
    else:
        return (path[:index], path[index + 1:])

def smoothen_array(arr):
    """
    Smoothen the input array by replacing each element with the average of itself and its neighbors.

    Parameters:
    - arr: List[int] : Input array of integers

    Returns:
    - List[int] : The modified array with smoothed values.
    """
    if not arr:
        return []

    n = len(arr)

    # Handle edge cases directly
    if n == 1:
        return arr

    smoothed_array = [0] * n

    for i in range(n):
        if i == 0:
            smoothed_array[i] = (arr[i] + arr[i + 1]) // 2
        elif i == n - 1:
            smoothed_array[i] = (arr[i - 1] + arr[i]) // 2
        else:
            smoothed_array[i] = (arr[i - 1] + arr[i] + arr[i + 1]) // 3

    return smoothed_array

def max_or_sum(a, b):
    """
    Returns the maximum of two numbers. 
    - If the numbers are equal, returns their sum.
    - If the numbers are complex, compares their magnitudes and returns the one with the greater magnitude.
      If the magnitudes are equal, returns their sum.
    """
    if isinstance(a, complex) or isinstance(b, complex):
        if abs(a) == abs(b):
            return a + b
        return a if abs(a) > abs(b) else b
    else:
        if a == b:
            return a + b
        return max(a, b)

def max_priority_tasks(T, tasks):
    # Sort tasks by end time (start time + duration)
    tasks.sort(key=lambda x: x[0] + x[1])

    dp = [0] * (T + 1) 

    for start_time, duration, priority in tasks:
        end_time = start_time + duration
        if end_time > T:
            continue
        for t in range(T, end_time - 1, -1):
            if t >= start_time + duration:
                dp[t] = max(dp[t], dp[start_time] + priority)

    return max(dp)

