def calculate_total_cost(items, shopping_list) -> float:
    """
    Calculates the total cost of the shopping list applying discounts from the items list.

    Parameters:
    - items (list of tuples): (item_id, price, discount_type, discount_param)
    - shopping_list (list of tuples): (item_id, quantity)

    Returns:
    - float: total cost after applying discounts
    """

    # Creating a dictionary for easy lookup of item details
    item_info = {item_id: (price, discount_type, discount_param) for item_id, price, discount_type, discount_param in items}

    total_cost = 0.0

    for item_id, quantity in shopping_list:
        if item_id in item_info:
            price, discount_type, discount_param = item_info[item_id]
            if discount_type == 'NONE':
                total_cost += price * quantity

            elif discount_type == 'BOGO':
                # Buy One Get One Free
                total_cost += price * (quantity // 2 + quantity % 2)

            elif discount_type == 'BTGO':
                # Buy Two Get One Free
                total_cost += price * (2 * (quantity // 3) + (quantity % 3))

            elif discount_type == 'PERCENT':
                # Bulk percentage discount
                percentage_discount = discount_param / 100.0
                total_cost += price * quantity * (1 - percentage_discount)

    return round(total_cost, 2)

def multiplyStrings(num1, num2):
    """
    Takes two non-negative integers as strings and returns their product as a string.
    """
    if num1 == "0" or num2 == "0":
        return "0"

    num1_length = len(num1)
    num2_length = len(num2)
    result = [0] * (num1_length + num2_length)

    for i in range(num1_length - 1, -1, -1):
        for j in range(num2_length - 1, -1, -1):
            product = int(num1[i]) * int(num2[j])
            sum_ = product + result[i + j + 1]

            result[i + j + 1] = sum_ % 10
            result[i + j] += sum_ // 10

    # Skip leading zeroes
    start = 0
    while start < len(result) and result[start] == 0:
        start += 1

    return ''.join(map(str, result[start:]))

def longest_common_subsequence(s1, s2):
    """
    Returns the length and the longest common subsequence (LCS) of two strings s1 and s2.
    """
    m, n = len(s1), len(s2)
    # Create a 2D array to store lengths of subsequence
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Build the dp array from bottom up
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Length of LCS is in dp[m][n]
    lcs_length = dp[m][n]

    # Create a variable to store the LCS string
    lcs = ''
    i, j = m, n
    while i > 0 and j > 0:
        if s1[i - 1] == s2[j - 1]:
            lcs = s1[i - 1] + lcs
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    return lcs_length, lcs

def longest_increasing_playlist(history):
    """
    Returns the length of the longest contiguous playlist of sequentially increasing song IDs.
    """
    if not history:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(history)):
        if history[i] == history[i - 1] + 1:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length

def max_diff_of_zeros(bin_str):
    """
    Returns the length of the longest sequence of consecutive zeros that 
    are surrounded by ones in the binary string bin_str.
    """
    max_len = 0
    current_len = 0
    inside_ones = False

    for char in bin_str:
        if char == '1':
            if inside_ones:
                if current_len > max_len:
                    max_len = current_len
            inside_ones = True
            current_len = 0
        elif char == '0':
            if inside_ones:
                current_len += 1
        else:
            raise ValueError("The input string should only contain '0' and '1' characters")

    return max_len

def decodeString(s, shift):
    """
    Decodes an encoded string where each alphabetic character is shifted by a given number of places.

    :param s: Encoded string
    :param shift: Integer shift value for decoding
    :return: Decoded string
    """
    decoded_chars = []
    for char in s:
        if char.isalpha():
            if char.isupper():
                decoded_chars.append(chr((ord(char) - shift - 65) % 26 + 65))
            elif char.islower():
                decoded_chars.append(chr((ord(char) - shift - 97) % 26 + 97))
        else:
            # Non-alphabet characters (e.g., spaces) remain unchanged
            decoded_chars.append(char)
    return ''.join(decoded_chars)

def move_zeros_inplace(array: list) -> None:
    """
    Move all zeros in the list to the end, preserving the order of other elements.
    """
    n = len(array)
    non_zero_index = 0  # Pointer to place the next non-zero element

    for current in range(n):
        if isinstance(array[current], bool) or array[current] != 0:
            array[non_zero_index], array[current] = array[current], array[non_zero_index]
            non_zero_index += 1

