def cycle_sort(arr):
    """
    Sorts the array using Cycle Sort algorithm and returns the sorted array.
    """
    writes = 0

    for cycle_start in range(0, len(arr) - 1):
        item = arr[cycle_start]

        # Find where to put the item
        pos = cycle_start
        for i in range(cycle_start + 1, len(arr)):
            if arr[i] < item:
                pos += 1

        # If the item is already in the correct position
        if pos == cycle_start:
            continue

        # Otherwise, put the item to the right position
        while item == arr[pos]:
            pos += 1
        arr[pos], item = item, arr[pos]
        writes += 1

        # Rotate the rest of the cycle
        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, len(arr)):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1
            arr[pos], item = item, arr[pos]
            writes += 1

    return arr

def are_permutations(str1: str, str2: str) -> bool:
    """
    Determines if str1 is a permutation of str2.

    Args:
    str1 (str): The first string.
    str2 (str): The second string.

    Returns:
    bool: True if str1 is a permutation of str2, False otherwise.
    """

    if len(str1) != len(str2):
        return False

    char_count = {}

    for char in str1:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char in str2:
        if char in char_count:
            char_count[char] -= 1
        else:
            return False

    for count in char_count.values():
        if count != 0:
            return False

    return True

def distinct_characters(s):
    """
    Returns a string with distinct characters from the input string `s` 
    in the order of their first appearance.
    """
    seen = set()
    result = []
    for char in s:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

