import heapq

def trap_rain_water(elevation_map):
    if not elevation_map or not elevation_map[0]:
        return 0

    m, n = len(elevation_map), len(elevation_map[0])
    visited = [[False] * n for _ in range(m)]
    heap = []

    # Add all the boundary cells to the heap
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                heapq.heappush(heap, (elevation_map[i][j], i, j))
                visited[i][j] = True

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    water_trapped = 0

    while heap:
        height, x, y = heapq.heappop(heap)

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                water_trapped += max(0, height - elevation_map[nx][ny])
                heapq.heappush(heap, (max(height, elevation_map[nx][ny]), nx, ny))

    return water_trapped

def fizz_buzz(number):
    """
    Returns "fizz" if the number is a multiple of 3,
    "buzz" if the number is a multiple of 5,
    "fizzbuzz" if the number is a multiple of both 3 and 5,
    otherwise, returns the number.
    """
    if number % 3 == 0 and number % 5 == 0:
        return "fizzbuzz"
    elif number % 3 == 0:
        return "fizz"
    elif number % 5 == 0:
        return "buzz"
    else:
        return str(number)

def is_valid_huffman_encoding(encoded_string: str, huffman_tree: dict) -> bool:
    """
    Returns True if the encoded_string can be decoded using the provided huffman_tree,
    otherwise returns False.
    """
    # Create a reverse lookup dictionary for easy matching of encodings to characters
    reverse_huffman_tree = {v: k for k, v in huffman_tree.items()}

    i = 0
    length = len(encoded_string)

    while i < length:
        match_found = False
        for code in reverse_huffman_tree:
            if encoded_string.startswith(code, i):
                i += len(code)
                match_found = True
                break
        if not match_found:
            return False

    return i == length

