def longest_climb_series(heights: List[int]) -> int:
    if len(heights) <= 1:
        return len(heights)

    max_length = 1
    current_length = 1
    current_diff = heights[1] - heights[0]

    for i in range(1, len(heights) - 1):
        diff = heights[i + 1] - heights[i]
        if diff == current_diff:
            current_length += 1
        else:
            current_diff = diff
            current_length = 1

        max_length = max(max_length, current_length + 1)  # Adding 1 to account for the starting element of the series

    return max_length

import pkgutil
import importlib
import sys

def list_package_content(package_name: str) -> dict:
    """
    List and categorize all modules, submodules, and subpackages within the specified package.

    Args:
    - package_name (str): The name of the package to analyze.

    Returns:
    - dict: Dictionary with "submodules" and "subpackages" as keys.
    """
    try:
        package = importlib.import_module(package_name)
    except ModuleNotFoundError:
        return {}

    package_path = package.__path__
    package_info = {
        "submodules": [],
        "subpackages": []
    }

    for finder, name, is_pkg in pkgutil.walk_packages(package_path, package_name + '.'):
        if is_pkg:
            package_info["subpackages"].append(name)
        else:
            package_info["submodules"].append(name)

    return package_info

