def longest_common_substring(words):
    """
    Finds the longest common substring that appears in all words.

    :param words: List of words
    :return: The longest common substring
    """
    if not words:
        return ""

    shortest_word = min(words, key=len)
    longest_substring = ""

    for i in range(len(shortest_word)):
        for j in range(i + 1, len(shortest_word) + 1):
            candidate = shortest_word[i:j]
            if all(candidate in word for word in words) and len(candidate) > len(longest_substring):
                longest_substring = candidate

    return longest_substring

def check_tic_tac_toe_winner(board: list) -> str:
    """
    Determines the winner of a Tic-Tac-Toe game or returns "Draw" if there is no winner.

    :param board: A 3x3 list of lists representing the Tic-Tac-Toe board.
    :return: "X", "O", or "Draw"
    """
    # Check rows and columns
    for i in range(3):
        if board[i][0] == board[i][1] == board[i][2] != " ":
            return board[i][0]
        if board[0][i] == board[1][i] == board[2][i] != " ":
            return board[0][i]

    # Check diagonals
    if board[0][0] == board[1][1] == board[2][2] != " ":
        return board[0][0]
    if board[0][2] == board[1][1] == board[2][0] != " ":
        return board[0][2]

    return "Draw"

