def compressed_length(s: str) -> int:
    """
    Returns the length of the string after applying basic string compression using the counts of repeated characters.
    If the compressed string is not shorter than the original, returns the length of the original string.
    """
    if not s:
        return 0

    compressed = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            compressed.append(s[i-1] + str(count))
            count = 1
    compressed.append(s[-1] + str(count))

    compressed_str = ''.join(compressed)
    return min(len(s), len(compressed_str))

def find_second_highest(nums):
    """
    Returns the second highest number in a list of integers without duplicates.
    If the list has fewer than 2 distinct elements, None is returned.
    """
    if len(nums) < 2:
        return None

    first, second = None, None

    for num in nums:
        if first is None or num > first:
            second = first
            first = num
        elif second is None or (num > second and num != first):
            second = num

    return second

def max_score(grid):
    """
    Returns the maximum score the player can achieve from top-left to bottom-right of the grid.
    """
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    dp = [[0]*cols for _ in range(rows)]

    dp[0][0] = grid[0][0]

    for i in range(1, cols):
        dp[0][i] = dp[0][i-1] + grid[0][i]

    for i in range(1, rows):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    for i in range(1, rows):
        for j in range(1, cols):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[rows-1][cols-1]

