    return second if second != float('-inf') else None

def calculate_average_scores(students):
    """
    Calculate the average score for each course from a list of student dictionaries.

    Args:
    students (list): List of dictionaries where each dictionary represents a student
                     and contains a 'courses' key with a dictionary of course: score pairs.

    Returns:
    dict: A dictionary where the keys are course names and the values are the average scores.
    """
    total_scores = {}
    count_scores = {}

    for student in students:
        for course, score in student['courses'].items():
            if course not in total_scores:
                total_scores[course] = 0
                count_scores[course] = 0
            total_scores[course] += score
            count_scores[course] += 1

    return {course: total_scores[course] / count_scores[course] for course in total_scores}

