def binary_search_insert_position(nums, target):
    """
    Searches for the target in the sorted list nums.
    Returns the index of the target if found.
    If the target is not found, returns the index where it should be inserted to maintain the sorted order.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
