    """
    Takes a sorted list of integers and returns a string that represents the ranges of consecutive numbers.
    """
    if not lst:
        return ""

    ranges = []
    start = lst[0]
    end = start

    for num in lst[1:]:
        if num == end + 1:
            end = num
        else:
            if start == end:
                ranges.append(f"{start}")
            else:
                ranges.append(f"{start}-{end}")
            start = num
            end = start

    if start == end:
