def max_non_adjacent_sum(nums: List[int]) -> int:
    if not nums:
        return 0

    if len(nums) == 1:
        return max(0, nums[0])

    incl = max(0, nums[0])  # max sum including the current element
    excl = 0                # max sum excluding the current element

    for i in range(1, len(nums)):
        new_excl = max(incl, excl)  # exclude current element
        incl = excl + nums[i]       # include current element
        excl = new_excl

    return max(incl, excl)

def unique_paths_with_obstacles(n, m, blocked):
    """
    Returns the number of unique paths from top-left to bottom-right of a grid 
    with given dimensions `n x m` while avoiding blocked cells.
    """

    # Create a grid initialized to 0s
    grid = [[0] * m for _ in range(n)]

    # Block the cells
    for (x, y) in blocked:
        grid[x-1][y-1] = -1  # convert to 0-indexed and mark as blocked

    # Start point should be 1 if it's not blocked
    if grid[0][0] == -1:
        return 0
    else:
        grid[0][0] = 1

    # Fill the first column
    for i in range(1, n):
        if grid[i][0] == -1:
            grid[i][0] = 0
        else:
            grid[i][0] = grid[i-1][0]

    # Fill the first row
    for j in range(1, m):
        if grid[0][j] == -1:
            grid[0][j] = 0
        else:
            grid[0][j] = grid[0][j-1]

    # Fill the rest of the grid
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == -1:
                grid[i][j] = 0
            else:
                if grid[i-1][j] != -1:
                    grid[i][j] += grid[i-1][j]
                if grid[i][j-1] != -1:
                    grid[i][j] += grid[i][j-1]

    return grid[n-1][m-1]

