def split_array_by_pattern(n: int, k: int, arr: List[int], pattern: List[int]) -> Union[List[int], int]:
    pattern_length = len(pattern)
    if n % k != 0 or pattern_length != n // k:
        return -1

    indices = []
    for i in range(0, n, pattern_length):
        if arr[i:i+pattern_length] != pattern:
            return -1
        if i > 0:
            indices.append(i + 1)  # Convert to 1-based indexing

    return indices if indices else -1

def isValid(s: str) -> str:
    bracket_map = {')': '(', '}': '{', ']': '['}
    open_brackets = set(['(', '{', '['])
    stack = []

    for char in s:
        if char in open_brackets:
            stack.append(char)
        elif char in bracket_map:
            if not stack or stack[-1] != bracket_map[char]:
                return "NO"
            stack.pop()

    return "YES" if not stack else "NO"

