def bit_manipulation(num: int, i: int, action: str, bit: int = None) -> int:
    """
    Perform bit manipulation on the given integer `num`.

    Parameters:
    - num: The integer to be manipulated.
    - i: The index of the bit to be manipulated.
    - action: The type of manipulation. One of 'get', 'set', 'clear', or 'update'.
    - bit: The value to set the bit to, applicable only for 'update'.

    Returns:
    - Result of the bit manipulation or the bit value for 'get' action.
    """

    # Perform the specified action
    if action == 'get':
        return (num >> i) & 1
    elif action == 'set':
        return num | (1 << i)
    elif action == 'clear':
        return num & ~(1 << i)
    elif action == 'update':
        if bit not in [0, 1]:
            raise ValueError("bit must be either 0 or 1 for 'update' action")
        return (num & ~(1 << i)) | (bit << i)
    else:
        raise ValueError("Invalid action. Choose from 'get', 'set', 'clear', 'update'.")

def optimized_selection_sort(arr):
    """
    Sorts an array of integers using an optimized selection sort algorithm.

    Introduces early stopping if the array is found to be already sorted during the process.

    :param arr: List of integers to be sorted.
    :return: List of integers sorted in ascending order.
    """
    n = len(arr)
    for i in range(n):
        min_idx = i
        for j in range(i+1, n):
            if arr[j] < arr[min_idx]:
                min_idx = j

        # Swap the found minimum element with the first element
        if min_idx != i:
            arr[i], arr[min_idx] = arr[min_idx], arr[i]

        # Check if the array is already sorted
        sorted = True
        for k in range(i+1, n-1):
            if arr[k] > arr[k+1]:
                sorted = False
                break
        if sorted:
            break

    return arr

