def selection_sort_descending(arr: List[int]) -> List[int]:
    n = len(arr)
    for i in range(n-1):
        # Find the index of the maximum element in the remaining unsorted part
        max_index = 0
        for j in range(1, n-i):
            if arr[j] > arr[max_index]:
                max_index = j
        # Swap it with the element at the end of the unsorted part
        arr[max_index], arr[n-i-1] = arr[n-i-1], arr[max_index]
    return arr

def extended_gcd(num1: int, num2: int) -> (int, int, int):
    """
    Returns the coefficients (s, t) and the GCD (g) of num1 and num2 such that:
    num1 * s + num2 * t = g
    """
    if num2 == 0:
        return (1, 0, num1)
    else:
        s, t, g = extended_gcd(num2, num1 % num2)
        return (t, s - (num1 // num2) * t, g)

def combination_dp(n, r):
    """
    Calculate the number of ways to choose r items from n items using dynamic programming.

    Parameters:
    n (int): Total items.
    r (int): Number of items to choose.

    Returns:
    int: Computed value of nCr.
    """
    if r > n:
        return 0
    if r == 0 or r == n:
        return 1

    # Initialize a 2D array to store the results of subproblems
    dp = [[0 for _ in range(r + 1)] for _ in range(n + 1)]

    # Calculate C(n, r) using bottom-up dynamic programming approach
    for i in range(n + 1):
        for j in range(min(i, r) + 1):
            if j == 0 or j == i:
                dp[i][j] = 1
            else:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]

    return dp[n][r]

import tokenize
from io import BytesIO

def transform_integers_to_hex(file_path: str) -> str:
    with open(file_path, 'rb') as f:
        tokens = tokenize.tokenize(f.readline)
        modified_tokens = []

        for token in tokens:
            if token.type == tokenize.NUMBER:
                try:
                    value = int(token.string)
                    if value < 0:
                        hex_value = f'-0x{-value:x}'
                    else:
                        hex_value = f'0x{value:x}'
                    modified_token = tokenize.TokenInfo(token.type, hex_value, 
                                                        token.start, token.end, token.line)
                except ValueError:
                    # In case the number is not an integer, keep it unchanged
                    modified_token = token
            else:
                modified_token = token
            modified_tokens.append(modified_token)

        # Use untokenize to convert back to source code
        modified_source = tokenize.untokenize(modified_tokens).decode('utf-8')
        return modified_source

import http.client
from typing import List, Tuple, Dict

def perform_requests(host: str, requests: List[Tuple[str, str, Dict[str, str], bytes]]) -> Dict[str, Dict[str, object]]:
    results = {}

    for method, url, headers, body in requests:
        try:
            conn = http.client.HTTPConnection(host)
            conn.request(method, url, body, headers)
            response = conn.getresponse()

            response_headers = {k: v for k, v in response.getheaders()}
            results[url] = {
                'status': response.status,
                'reason': response.reason,
                'response_headers': response_headers,
                'body': response.read()
            }
        except (http.client.HTTPException, OSError) as e:
            results[url] = {
                'status': None,
                'reason': str(e),
                'response_headers': {},
                'body': b''
            }
        finally:
            conn.close()

    return results

