    """
    Returns True if the input string is a well-formed mathematical expression 
    using parentheses, brackets, and curly braces; otherwise, returns False.
    """
    stack = []
    matching_pairs = {')': '(', ']': '[', '}': '{'}

    for char in expression:
        if char in matching_pairs.values():
            stack.append(char)
        elif char in matching_pairs.keys():
            if stack == [] or matching_pairs[char] != stack.pop():
                return False
        else:
            # Ignore non-bracket characters
            continue

    return stack == []

