    # Initialize a dictionary with each lowercase letter set to 0
    letter_counts = {letter: 0 for letter in ascii_lowercase}

    # Increment counts for each lowercase letter in the string
    for char in s:
        if char in ascii_lowercase:
            letter_counts[char] += 1

    # Remove from dictionary letters that did not appear in the string
    letter_counts = {k: v for k, v in letter_counts.items() if v > 0}

    return letter_counts

def common_elements(list1, list2):
    """
    Returns a list of elements that are common in both list1 and list2.
    The time complexity of this solution is O(n), where n is the length of the longer list.
    """
    # Using a dictionary to track elements in list1
    elements_dict = {}
    result = []

    # Traverse the first list and add elements to the dictionary
    for element in list1:
        if element not in elements_dict:
            elements_dict[element] = True

    # Traverse the second list and collect elements that are in dictionary
    for element in list2:
        if element in elements_dict:
            result.append(element)
            # Remove the element from dictionary to avoid duplicates in the result
            del elements_dict[element]

    return result

import numpy as np

def create_array_from_range(range_str):
    """
    Converts a range in the form of a string like "1:10" or "5:-5:2"
    into a NumPy array with a starting number, end number, and optional step value.
    """
    parts = range_str.split(':')

    if len(parts) == 3:
        start, end, step = map(int, parts)
    else:
        start, end = map(int, parts)
        step = 1

    return np.arange(start, end, step)

def filter_negatives(lst):
    """
    Returns a new list with all the negative values filtered out using a recursive approach.
    """
    if not lst:
        return []
    elif lst[0] >= 0:
        return [lst[0]] + filter_negatives(lst[1:])
    else:
        return filter_negatives(lst[1:])

def replace_hello_with_goodbye(s):
    """
    Replace the word 'Hello' with 'Goodbye' in the string s, while handling different cases.
    The function will not replace substrings containing 'Hello'.
    """
    words = s.split()

    for i, word in enumerate(words):
        # Strip word of punctuation for comparison
        stripped_word = word.strip(".,!?")
        if stripped_word.lower() == "hello":
            words[i] = word.replace(stripped_word, "Goodbye")

    return " ".join(words)

import numpy as np

def sum_matrices(*matrices):
    """
    Returns the sum of an arbitrary number of matrices. Each matrix is a 2D NumPy array.
    If no matrices are provided, returns a message indicating that.
    If any matrices have differing dimensions, raises a ValueError.
    """
    if len(matrices) == 0:
        return "No matrices provided"

    # Check that all matrices have the same dimensions
    first_matrix_shape = matrices[0].shape
    for matrix in matrices:
        if matrix.shape != first_matrix_shape:
            raise ValueError("All matrices must have the same dimensions")

    return np.sum(matrices, axis=0)

