def reverse_vowels(s):
    """
    Takes a string s and reverses only the vowels in it while leaving the rest 
    of the characters in their original positions.
    """
    vowels = "aeiouAEIOU"
    s_list = list(s)
    i, j = 0, len(s_list) - 1

    while i < j:
        if s_list[i] in vowels and s_list[j] in vowels:
            s_list[i], s_list[j] = s_list[j], s_list[i]
            i += 1
            j -= 1
        if s_list[i] not in vowels:
            i += 1
        if s_list[j] not in vowels:
            j -= 1

    return ''.join(s_list)

import select
import errno

def wait_fd(fd, flags, timeout, retry_on_intr=False):
    """
    Waits for a file descriptor to be ready for reading, writing, or both.

    Parameters:
        fd (int): The file descriptor to wait on.
        flags (int): Specifies the event to wait for (1 for readable, 2 for writable).
        timeout (int): The timeout duration in microseconds.
        retry_on_intr (bool): Whether to retry if interrupted by a signal.

    Returns:
        int: The number of file descriptors ready for the specified events.
    """
    read_fds = []
    write_fds = []
    if flags & 1:
        read_fds.append(fd)
    if flags & 2:
        write_fds.append(fd)

    timeout_sec = timeout / 1_000_000.0

    while True:
        try:
            ready_fds = select.select(read_fds, write_fds, [], timeout_sec)
            return len(ready_fds[0]) + len(ready_fds[1])
        except select.error as e:
            if e.args[0] == errno.EINTR and retry_on_intr:
                continue
            else:
                raise

