def length_of_longest_substring_k_distinct(s, k):
    """
    Returns the length of the longest contiguous substring with exactly k distinct characters.
    If there is no such substring, returns -1.
    """
    if k == 0:
        return -1

    left = 0
    max_length = -1
    char_map = {}

    for right in range(len(s)):
        char_map[s[right]] = char_map.get(s[right], 0) + 1

        while len(char_map) > k:
            char_map[s[left]] -= 1
            if char_map[s[left]] == 0:
                del char_map[s[left]]
            left += 1

        if len(char_map) == k:
            max_length = max(max_length, right - left + 1)

    return max_length

def find_longest_divisible_subsequence(nums):
    """
    Finds the length of the longest subsequence such that each element in the subsequence is divisible by the previous one.
    :param nums: List of integers
    :return: Length of the longest divisible subsequence
    """
    if not nums:
        return 0

    # Sort the array
    nums.sort()
    n = len(nums)

    # dp array to hold the longest subsequence length ending at each element
    dp = [1] * n

    # Iterate through the array to build up the dp array
    for i in range(1, n):
        for j in range(i):
            if nums[i] % nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def min_slicing_operations(nums):
    """
    Returns the minimum number of slicing operations required to sort nums in non-decreasing order.
    """
    if not nums:
        return 0

    sorted_nums = sorted(nums)
    n = len(nums)

    start, end = None, None

    for i in range(n):
        if nums[i] != sorted_nums[i]:
            if start is None:
                start = i
            end = i

    if start is None:
        return 0  # Already sorted

    if nums[start:end+1] == sorted_nums[start:end+1][::-1]:
        return 1

    return 2

def max_subarray_sum(nums):
    """
    Find the contiguous subarray within an array, `nums`, which has the largest sum, and return its sum.
    """
    if not nums:
        return 0

    max_current = max_global = nums[0]
    for num in nums[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current

    return max_global

def rob(nums, k):
    """
    Returns the maximum amount of money that can be robbed from the houses,
    considering that after robbing one house, you must skip at least k houses.

    :param nums: List[int] - list of integers representing the amount of money at each house
    :param k: int - the number of houses you must skip after robbing one house
    :return: int - the maximum amount of money you can rob
    """
    if not nums:
        return 0

    n = len(nums)
    if k >= n:
        return max(nums)

    dp = [0] * n
    dp[0] = nums[0]

    for i in range(1, n):
        if i <= k:
            dp[i] = max(dp[i-1], nums[i])
        else:
            dp[i] = max(dp[i-1], nums[i] + dp[i-k-1])

    return max(dp)

def length_of_longest_special_subarray(arr):
    """
    Returns the length of the longest special subarray from the given array.
    A special subarray has at least 3 distinct elements.
    """
    n = len(arr)
    if n < 3:
        return 0

    max_len = 0
    start = 0
    seen = {}

    for end in range(n):
        if arr[end] in seen and seen[arr[end]] >= start:
            start = seen[arr[end]] + 1
        seen[arr[end]] = end

        current_subarray_length = end - start + 1
        if current_subarray_length >= 3:
            max_len = max(max_len, current_subarray_length)

    return max_len

def len_longest_fib_subseq(nums):
    if len(nums) < 3:
        return 0

    index = {x: i for i, x in enumerate(nums)}
    longest = {}
    max_len = 0

    for k in range(len(nums)):
        for j in range(k):
            i = index.get(nums[k] - nums[j], None)
            if i is not None and i < j:
                seq_len = longest.get((i, j), 2) + 1
                longest[j, k] = seq_len
                max_len = max(max_len, seq_len)

    return max_len if max_len >= 3 else 0

