def min_sessions(tasks, sessionTime):
    """
    Returns the minimum number of sessions needed to complete all tasks given that the sum
    of task durations in each session should not exceed sessionTime.
    """
    n = len(tasks)
    dp = [float('inf')] * (1 << n)
    dp[0] = 1

    # Calculate the sum of the tasks for each subset
    subset_sum = [0] * (1 << n)
    for mask in range(1 << n):
        total = 0
        for i in range(n):
            if mask & (1 << i):
                total += tasks[i]
        subset_sum[mask] = total

    # Dynamic programming to find the minimum number of sessions
    for mask in range(1 << n):
        if subset_sum[mask] <= sessionTime:
            dp[mask] = 1
        else:
            submask = mask
            while submask:
                if subset_sum[submask] <= sessionTime:
                    dp[mask] = min(dp[mask], dp[mask ^ submask] + 1)
                submask = (submask - 1) & mask

    return dp[(1 << n) - 1]

def min_operations(initialState, finalState):
    if sorted(initialState) != sorted(finalState):
        return -1

    n = len(initialState)
    ops = 0
    j = n - 1

    for i in range(n - 1, -1, -1):
        if initialState[i] == finalState[j]:
            j -= 1
        else:
            ops += 1

    return ops

def countCharacters(words, chars):
    from collections import Counter

    chars_count = Counter(chars)
    total_length = 0

    for word in words:
        word_count = Counter(word)
        if all(word_count[c] <= chars_count[c] for c in word_count):
            total_length += len(word)

    return total_length

def balance_parentheses(s):
    """
    Determines if the given string can be balanced by treating '*' as either '(', ')' or ''.
    """
    low = high = 0  # low: minimum number of unmatched '(', high: maximum number of unmatched '('

    for char in s:
        if char == '(':
            low += 1
            high += 1
        elif char == ')':
            if low > 0:
                low -= 1
            high -= 1
        elif char == '*':
            if low > 0:
                low -= 1
            high += 1

        if high < 0:  # more ')' than '(' at any point
            return False

    return low == 0  # if low is 0, it means we can balance the string

def count_word_occurrences(strings):
