    keys are words and the values are the counts of their occurrences.
    """
    word_count = {}
    for string in strings:
        words = string.split()
        for word in words:
            word_count[word] = word_count.get(word, 0) + 1

    return word_count

def max_profit_with_k_transactions(prices, k):
    if not prices or k == 0:
        return 0

    n = len(prices)

    if k >= n // 2:  # In this case, it's equivalent to unlimited transactions
        return sum(max(prices[i + 1] - prices[i], 0) for i in range(n - 1))

    dp = [[0] * n for _ in range(k + 1)]

    for t in range(1, k + 1):
        max_diff = -prices[0]
        for d in range(1, n):
            dp[t][d] = max(dp[t][d - 1], prices[d] + max_diff)
            max_diff = max(max_diff, dp[t - 1][d] - prices[d])

    return dp[k][n - 1]

def find_nth_prime(n):
    """
    Returns the nth prime number.
    """
    if n < 1:
        raise ValueError("n must be a positive integer")

    primes = []
    num = 2

    while len(primes) < n:
        is_prime = True
        for prime in primes:
            if num % prime == 0:
                is_prime = False
                break

        if is_prime:
            primes.append(num)

        num += 1

    return primes[-1]

def fibonacci(n):
    """
    Returns the Fibonacci number at the given position n.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def generate_sequence(n):
    """
    Generates a sequence of numbers based on the argument passed.
    If n is negative, generates a sequence from n to 0.
    If n is positive, generates a sequence from 1 to n.
    If n is 0, returns "0".

    Args:
    n (int): The boundary of the sequence.

    Returns:
    str: The generated sequence as a string.
    """
    if n == 0:
        return "0"
    elif n > 0:
        return " ".join(map(str, range(1, n + 1)))
    else:
        return " ".join(map(str, range(n, 1)))

def max_subarray_sum(arr):
    """
    Returns the maximum sum of a subarray in an integer array using Kadane's Algorithm.
    """
    if not arr:
        return 0

    current_max = global_max = arr[0]
    for num in arr[1:]:
        current_max = max(num, current_max + num)
        if current_max > global_max:
            global_max = current_max

    return global_max

def count_zero_bits(n):
    """
    Returns the number of zero bits in the binary representation of the integer n.
    """
    if n == 0:
        return 1

    binary_representation = bin(n)[2:]  # Get the binary representation of the number without the '0b' prefix
    return binary_representation.count('0')

