def most_frequent_element(lst):
    """
    Returns the most frequent element in a list.
    If there are multiple elements with the same highest frequency, returns the one that appears first.
    If the list is empty, returns None.
    """
    if not lst:
        return None

    frequency_dict = {}
    for element in lst:
        if element in frequency_dict:
            frequency_dict[element] += 1
        else:
            frequency_dict[element] = 1

    most_frequent = lst[0]
    max_frequency = frequency_dict[most_frequent]

    for element in lst:
        if frequency_dict[element] > max_frequency:
            most_frequent = element
            max_frequency = frequency_dict[element]

    return most_frequent

