def roman_to_int(s):
    """
    Convert Roman numeral string to integer. Handles cases with leading "X" repeated multiple times.
    """
    roman_values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 
        'C': 100, 'D': 500, 'M': 1000
    }

    total = 0
    prev_value = 0
    for char in reversed(s):
        value = roman_values[char]

        if value >= prev_value:
            total += value
        else:
            total -= value

        prev_value = value

    return total

def sum_of_squares(n):
    """
    Returns the sum of the squares of the first n natural numbers using recursion.
    """
    if n <= 0:
        return 0
    return n * n + sum_of_squares(n - 1)

def is_balanced(s):
    """
    Returns True if the string contains a balanced set of brackets, otherwise False.
    """
    stack = []
    opening_brackets = set('({[')
    closing_brackets = set(')}]')
    matching_brackets = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if not stack or stack[-1] != matching_brackets[char]:
                return False
            stack.pop()

    return len(stack) == 0

def elements_with_frequency_greater_than_one(data):
    """
    Returns elements with a frequency of occurrence greater than 1.

    Parameters:
    data (str, list, dict): The input data which can be a string, list, or dictionary.

    Returns:
    list/str/keys: Elements with frequency greater than 1.
    """
    from collections import Counter

    if isinstance(data, dict):
        counter = Counter(data.values())
    else:
        counter = Counter(data)

    if isinstance(data, dict):
        return [k for k, v in data.items() if counter[v] > 1]
    elif isinstance(data, list):
        return [k for k, v in counter.items() if v > 1]
    elif isinstance(data, str):
        return ''.join([k for k, v in counter.items() if v > 1])
    else:
        raise TypeError("Unsupported input type")

