    Returns a list of peak elements in the array. A peak element is one that is not smaller than its neighbors.
    """
    n = len(arr)
    if n == 0:
        return []

    peaks = []

    for i in range(n):
        # Check if the current element is a peak
        if (i == 0 or arr[i] >= arr[i - 1]) and (i == n - 1 or arr[i] >= arr[i + 1]):
            peaks.append(arr[i])

    return peaks

def sum_of_divisors(n):
    """
    Returns the sum of all divisors of n, excluding n itself.
    """
    if n < 1:
        return 0

    sum_divisors = 0
    for i in range(1, n):
        if n % i == 0:
            sum_divisors += i
    return sum_divisors

def smallest_window(s):
    """
    Determines the smallest window that contains an equal number of 'X' and 'Y'.

    Parameters:
    s (str): string containing only characters 'X' and 'Y'

    Returns:
    int: length of the smallest window containing an equal number of 'X' and 'Y'
         or -1 if no such window exists.
    """
    n = len(s)
    if n == 0:
        return -1

    # Dictionary to store the net count of 'X' minus 'Y' and their first occurrence index
    net_count_dict = {0: -1}
    net_count = 0
    min_length = float('inf')

    for i in range(n):
        if s[i] == 'X':
            net_count += 1
        else:
            net_count -= 1

        if net_count in net_count_dict:
            min_length = min(min_length, i - net_count_dict[net_count])
        else:
            net_count_dict[net_count] = i

    return min_length if min_length != float('inf') else -1

