from typing import List

def make_unique_variables(variable_names: List[str]) -> List[str]:
    """
    Generates a list of unique variable names by appending the smallest possible positive integer to duplicate names.
    """
    name_count = {}
    unique_names = []

    for name in variable_names:
        if name not in name_count:
            unique_names.append(name)
            name_count[name] = 1
        else:
            new_name = f"{name}{name_count[name]}"
            while new_name in name_count:
                name_count[name] += 1
                new_name = f"{name}{name_count[name]}"
            unique_names.append(new_name)
            name_count[new_name] = 1
            name_count[name] += 1

    return unique_names

def lis(lst):
    """
    Finds the longest increasing subsequence in a given list of integers.
    """
    if not lst: 
        return []

    # Array to store our subsequence
    lis = [lst[0]]

    # Dictionary to track the actual sequences
    sequences = {lst[0]: [lst[0]]}

    for num in lst[1:]:
        if num > lis[-1]:
            lis.append(num)
            sequences[num] = sequences[lis[-2]] + [num]
        else:
            for i in range(len(lis)):
                if num <= lis[i]:
                    lis[i] = num
                    sequences[num] = sequences[lis[i-1]] + [num] if i > 0 else [num]
                    break

    # Returning the longest increasing subsequence based on tracked sequences
    return sequences[lis[-1]]

def uniqueKLengthSubarrays(nums, k):
    """
    Returns the number of unique k-length continuous subarrays that have a sum which is a multiple of k.
    """
    count = 0
    for i in range(len(nums) - k + 1):
        subarray_sum = sum(nums[i:i + k])
        if subarray_sum % k == 0:
            count += 1
    return count

def compress_string(s):
    """
    Takes a string as input and returns a new string where consecutive occurrences of the 
    same character are replaced with that character followed by the count of duplicates.
    """
    if not s:
        return ""

    compressed = []
    count = 1
    last_char = s[0]

    for char in s[1:]:
        if char == last_char:
            count += 1
        else:
            compressed.append(f"{last_char}{count}")
            last_char = char
            count = 1

    compressed.append(f"{last_char}{count}")

    return ''.join(compressed)

def longestUniqueSkillsSubarray(N, skills):
    """
    Find the length of the longest sub-array with the maximum number of unique skills.
    """
    skill_index = {}
    max_length = 0
    start = 0

    for end in range(N):
        if skills[end] in skill_index:
            start = max(start, skill_index[skills[end]] + 1)

        skill_index[skills[end]] = end
        max_length = max(max_length, end - start + 1)

    return max_length

def longestWorkingDays(days):
    """
    Returns the longest sequence of consecutive working days (Monday to Friday, i.e., 1 to 5).
    """
    max_sequence = []
    current_sequence = []
    for day in days:
        if 1 <= day <= 5:
            current_sequence.append(day)
        else:
            if len(current_sequence) > len(max_sequence):
                max_sequence = current_sequence
            current_sequence = []

    if len(current_sequence) > len(max_sequence):
        max_sequence = current_sequence

    return max_sequence

def minStepsToAnagram(str1, str2):
    from collections import Counter

    # Count frequency of each character in both strings
    count1 = Counter(str1)
    count2 = Counter(str2)

    # Calculate the number of deletions or insertions needed to make the two strings anagrams
    deletions = 0
    for char in count1:
        if char in count2:
            deletions += abs(count1[char] - count2[char])
        else:
            deletions += count1[char]

    for char in count2:
        if char not in count1:
            deletions += count2[char]

    return deletions

def crush_string(s):
    # Base case: empty string
    if not s:
        return s

    # Initialize a stack to track characters
    stack = []

    for char in s:
        # If stack is empty, add current character
        if not stack:
            stack.append(char)
        # If current character is different from the last character in the stack
        elif stack[-1] != char:
            stack.append(char)
        # If current character is an asterisk or the same as the last character in the stack
        else:
            continue

    # Return the string representation of the stack
    return ''.join(stack)

def all_components_functioning(matrix):
    """
    Returns True if all components in the 10x10 matrix are functioning properly, otherwise False.
    Uses bitwise operators only.
    """
    result = True
    for row in matrix:
        for value in row:
            result = result & value
    return result

from collections import deque

def min_time_to_exit(grid):
    """
    Returns the minimum time required for all occupants to reach an exit, or -1 if not possible.
    """
    rows, cols = len(grid), len(grid[0])
    queue = deque()
    time = [[float('inf')] * cols for _ in range(rows)]  # Time matrix

    # Collect all exits and initiate BFS search from them
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                queue.append((r, c, 0))  # (row, col, time)
                time[r][c] = 0  # Time to reach exit from an exit is 0

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while queue:
        r, c, t = queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != 2 and t + 1 < time[nr][nc]:
                time[nr][nc] = t + 1
                queue.append((nr, nc, t + 1))

    max_time = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                if time[r][c] == float('inf'):
                    return -1
                max_time = max(max_time, time[r][c])

    return max_time

def maximum_product_of_three(nums):
    """
    Returns the maximum product that can be obtained from any three numbers in the list.
    """
    if len(nums) < 3:
        raise ValueError("The input list must have at least three numbers.")

    # Initialize variables to store the three largest and two smallest numbers
    max1 = max2 = max3 = float('-inf')
    min1 = min2 = float('inf')

    for num in nums:
        # Update the maximum values
        if num > max1:
            max3 = max2
            max2 = max1
            max1 = num
        elif num > max2:
            max3 = max2
            max2 = num
        elif num > max3:
            max3 = num

        # Update the minimum values
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Calculate the maximum product of three numbers
    return max(max1 * max2 * max3, max1 * min1 * min2)

def count_elements(nested_dict):
    """
    Returns the total number of elements in a nested dictionary.
    """
    count = 0
    for key, value in nested_dict.items():
        count += 1
        if isinstance(value, dict):
            count += count_elements(value)
    return count

def first_non_repeated_character(s):
    """
    Returns the first non-repeated character in the string s.
    If no such character exists, returns -1.
    """
    char_count = {}

    # Count each character in the string
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the first character with count 1
    for char in s:
        if char_count[char] == 1:
            return char

    return -1

def rotate_180(matrix):
    """
    Rotates the given N x N matrix by 180 degrees.
    """
    n = len(matrix)
    for i in range(n):
        for j in range(n):
            if i * n + j < (n * n) // 2:
                opp_i, opp_j = n - 1 - i, n - 1 - j
                matrix[i][j], matrix[opp_i][opp_j] = matrix[opp_i][opp_j], matrix[i][j]

    return matrix

def first_missing_positive(nums):
    """
    Returns the first missing positive number in the given list of integers.
    """
    n = len(nums)

    # Mark numbers (num < 0) and (num > n) with a special marker number (n+1)
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = n + 1

    # Use index as a hash key and number sign as a presence detector
    for i in range(n):
        num = abs(nums[i])
        if num <= n:
            nums[num - 1] = -abs(nums[num - 1])

    # The first index of a positive number is the missing smallest positive number
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    return n + 1

def longest_two_char_substring(s: str) -> str:
    if len(s) < 2:
        return ""

    start = 0
    max_length = 0
    max_substr = ""
    char_count = {}

    for end, char in enumerate(s):
        char_count[char] = char_count.get(char, 0) + 1

        while len(char_count) > 2:
            char_count[s[start]] -= 1
            if char_count[s[start]] == 0:
                del char_count[s[start]]
            start += 1

        current_length = end - start + 1
        if current_length > max_length:
            max_length = current_length
            max_substr = s[start:end + 1]

    return max_substr

def unique_paths_with_obstacles(obstacle_grid):
    """
    Returns the number of unique paths in a grid with obstacles.

    Parameters:
    obstacle_grid (List[List[int]]): 2D array representing the grid where 0 represents a free cell and 1 represents an obstacle.

    Returns:
    int: Number of unique paths from the top-left corner to the bottom-right corner.
    """
    if not obstacle_grid or obstacle_grid[0][0] == 1:
        return 0

    nrows, ncols = len(obstacle_grid), len(obstacle_grid[0])

    # Create a DP table with the same dimensions as the obstacle_grid
    dp = [[0] * ncols for _ in range(nrows)]

    # Initialize the starting point
    dp[0][0] = 1

    # Fill in the DP table
    for r in range(nrows):
        for c in range(ncols):
            if obstacle_grid[r][c] == 1:
                dp[r][c] = 0
            else:
                if r > 0:
                    dp[r][c] += dp[r-1][c]
                if c > 0:
                    dp[r][c] += dp[r][c-1]

    return dp[-1][-1]

from typing import List, Dict
import fnmatch

def match_filenames(filenames: List[str], patterns: List[str]) -> Dict[str, Dict[str, List[str]]]:
    result = {}

    for pattern in patterns:
        case_insensitive_matches = [filename for filename in filenames if fnmatch.fnmatch(filename.lower(), pattern.lower())]
        case_sensitive_matches = [filename for filename in filenames if fnmatch.fnmatchcase(filename, pattern)]

        result[pattern] = {
            "case_insensitive": case_insensitive_matches,
            "case_sensitive": case_sensitive_matches
        }

    return result

def prime_factors(n):
    """
    Returns a list of all prime factors of n in ascending order.
    """
    factors = []
    divisor = 2
    while n >= 2:
        if n % divisor == 0:
            if divisor not in factors:
                factors.append(divisor)
            n //= divisor
        else:
            divisor += 1
    return factors

def minimal_write_sort(arr):
    """
    Sort an array using Cycle Sort, minimizing the number of write operations.
    """
    n = len(arr)

    for cycle_start in range(n - 1):
        item = arr[cycle_start]

        pos = cycle_start
        for i in range(cycle_start + 1, n):
            if arr[i] < item:
                pos += 1

        if pos == cycle_start:
            continue

        while item == arr[pos]:
            pos += 1

        arr[pos], item = item, arr[pos]

        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, n):
                if arr[i] < item:
                    pos += 1
            while item == arr[pos]:
                pos += 1
            arr[pos], item = item, arr[pos]

    return arr

def longest_constant_interval(distances):
    """
    Returns the starting and ending seconds of the longest continuous interval 
    where the vehicle traveled the same distance every second.
    """
    n = len(distances)
    if n == 0:
        return ""

    max_start, max_end = 0, 0
    current_start = 0

    for i in range(1, n):
        if distances[i] != distances[current_start]:
            if (i - current_start) > (max_end - max_start + 1):
                max_start, max_end = current_start, i - 1
            current_start = i

    if (n - current_start) > (max_end - max_start + 1):
        max_start, max_end = current_start, n - 1

    return f"{max_start}-{max_end}"

def min_completion_time(tasks):
    """
    Returns the minimized maximum completion time for distributing tasks between two people.
    """
    tasks.sort(reverse=True)
    time_A, time_B = 0, 0

    for task in tasks:
        if time_A <= time_B:
            time_A += task
        else:
            time_B += task

    return max(time_A, time_B)

def pair_elements(list1, list2):
    """
    Create a list of pairs where each pair is created by combining elements
    from the lists based on their positions.
    """
    combined_list = []

    for sublist1, sublist2 in zip(list1, list2):
        for x, y in zip(sublist1, sublist2):
            combined_list.append((x, y))

    return combined_list

def next_greater_element(arr):
    stack = []
    result = [-1] * len(arr)

    for i in range(len(arr)):
        while stack and arr[i] > arr[stack[-1]]:
            result[stack.pop()] = arr[i]
        stack.append(i)

    return result

def recursive_selection_sort(arr, n=None, index=0):
    """
    Sorts a list in descending order using a recursive selection sort algorithm.
    """
    if n is None:
        n = len(arr)

    # Base case: if the entire list is sorted
    if index == n:
        return arr

    # Find the maximum element in the unsorted part of the list
    max_index = index
    for j in range(index + 1, n):
        if arr[j] > arr[max_index]:
            max_index = j

    # Swap the found maximum element with the first element
    arr[index], arr[max_index] = arr[max_index], arr[index]

    # Recursively sort the rest of the list
    return recursive_selection_sort(arr, n, index + 1)

from typing import List

def fibonacci_modulo(n: int, mod: int) -> List[int]:
    if n == 0:
        return [0]
    if n == 1:
        return [0, 1]

    fib = [0, 1]
    for i in range(2, n + 1):
        fib.append((fib[-1] + fib[-2]) % mod)

    return fib

import math

def find_perfect_squares(numbers):
    """
    Returns a list of unique perfect squares from the input list.
    """
    perfect_squares = set()
    for num in numbers:
        if num >= 0:  # only non-negative numbers can be perfect squares
            root = int(math.isqrt(num))
            if root * root == num:
                perfect_squares.add(num)
    return sorted(perfect_squares)

def max_subarray_sum(nums):
    """
    Finds the maximum sum of a contiguous subarray within a one-dimensional array of numbers.
    Returns the maximum sum and the subarray itself.
    """
    if not nums:
        return 0, []

    max_sum = current_sum = nums[0]
    start = end = temp_start = 0

    for i in range(1, len(nums)):
        if nums[i] > current_sum + nums[i]:
            current_sum = nums[i]
            temp_start = i
        else:
            current_sum += nums[i]

        if current_sum > max_sum:
            max_sum = current_sum
            start = temp_start
            end = i

    return max_sum, nums[start:end+1]

def max_sum_of_mins(nums, k):
    # Sort the nums array
    sorted_nums = sorted(nums)
    # We need to pick the first k elements of the sorted array since they are the minimum
    return sum(sorted_nums[:k])

def min_flowers_after_nights(nums, d):
    """
    Return the minimum number of flowers that could be present in any garden after d nights.
    """
    n = len(nums)

    for _ in range(d):
        new_nums = nums.copy()
        for i in range(1, n-1):
            new_nums[i] = min(new_nums[i], nums[i-1], nums[i+1])
        if n > 1:
            new_nums[0] = min(new_nums[0], nums[1])
            new_nums[-1] = min(new_nums[-1], nums[n-2])
        nums = new_nums

    return min(nums)

from typing import List

def cycle_sort(arr: List[int]) -> List[int]:
    """
    Sorts an array using Cycle Sort to minimize the number of write operations.
    """
    n = len(arr)

    # Traverse the array and place each element to its correct position
    for start in range(n - 1):
        item = arr[start]

        # Find the position where we put the element
        pos = start
        for i in range(start + 1, n):
            if arr[i] < item:
                pos += 1

        # If the item is already in the correct position
        if pos == start:
            continue

        # Otherwise place the item where it needs to be
        while item == arr[pos]:
            pos += 1
        arr[pos], item = item, arr[pos]

        # Rotate the rest of the cycle
        while pos != start:
            pos = start
            for i in range(start + 1, n):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1
            arr[pos], item = item, arr[pos]

    return arr

def longest_alternating_subsequence(nums):
    n = len(nums)
    if n == 0:
        return 0

    up = [1] * n
    down = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                up[i] = max(up[i], down[j] + 1)
            elif nums[i] < nums[j]:
                down[i] = max(down[i], up[j] + 1)

    return max(max(up), max(down))

