def convert_value(value):
    """
    Converts a basic string value based on certain conditions.
    """
    if value is None:
        return "None"
    elif value.isdigit():
        return int(value)
    elif value.replace('.', '', 1).isdigit() and value.count('.') < 2:
        return float(value)
    else:
        return value

def is_3d_array_ascending(arr):
    """
    Verifies if all the elements in a given 3D array are in ascending order depth-wise, row-wise, and column-wise.

    :param arr: List of Lists of Lists
    :return: Boolean
    """

    if not arr:
        return True

    depth = len(arr)
    rows = len(arr[0])
    cols = len(arr[0][0])

    for d in range(depth):
        for r in range(rows):
            for c in range(cols):
                if (
                    d > 0 and arr[d][r][c] < arr[d-1][r][c] or
                    r > 0 and arr[d][r][c] < arr[d][r-1][c] or
                    c > 0 and arr[d][r][c] < arr[d][r][c-1]
                ):
                    return False
    return True

