def max_subsequence_sum(nums: List[int]) -> int:
    """
    Returns the maximum possible sum of a non-empty subsequence.
    """
    # If all numbers are negative, return the maximum number
    if all(x < 0 for x in nums):
        return max(nums)

    # Sum of all positive numbers in the list
    total_sum = 0
    for num in nums:
        if num > 0:
            total_sum += num

    return total_sum

def minTravelTime(n, m, edges):
    import itertools

    # Create an adjacency matrix with high initial values (inf for practicality)
    inf = float('inf')
    graph = [[inf]*n for _ in range(n)]

    # Fill the adjacency matrix with edge values
    for u, v, w in edges:
        graph[u-1][v-1] = w
        graph[v-1][u-1] = w

    # Initialize dp array with inf values, dimensions [2^n][n]
    dp = [[inf] * n for _ in range(1 << n)]
    # Starting point: visiting first node
    dp[1][0] = 0

    # Iterate over every subset of vertices
    for mask in range(1 << n):
        for u in range(n):
            if mask & (1 << u):
                for v in range(n):
                    if mask & (1 << v) == 0:
                        next_mask = mask | (1 << v)
                        dp[next_mask][v] = min(dp[next_mask][v], dp[mask][u] + graph[u][v])

    # The answer will be the minimum value of returning to the starting node after visiting all nodes
    min_time = inf
    for u in range(1, n):
        min_time = min(min_time, dp[(1 << n) - 1][u] + graph[u][0])

    return min_time

def decode_string(encoded: str) -> str:
    stack = []
    curr_num = 0
    curr_str = ''

    for c in encoded:
        if c.isdigit():
            curr_num = curr_num * 10 + int(c)
        elif c == '[':
            stack.append((curr_str, curr_num))
            curr_str = ''
            curr_num = 0
        elif c == ']':
            last_str, num = stack.pop()
            curr_str = last_str + curr_str * num
        else:
            curr_str += c

    return curr_str

def intersect_lists(list1, list2):
