    """
    intersecting_elements = []
    for elem in list1:
        if elem in list2 and elem not in intersecting_elements:
            intersecting_elements.append(elem)
    return intersecting_elements

from typing import List, Tuple, Dict
import ipaddress

def validate_and_report(ip_network_pairs: List[Tuple[str, str]]) -> dict:
    report = {
        "valid_pairs": [],
        "invalid_entries": [],
        "network_sizes": {}
    }

    for ip_str, network_str in ip_network_pairs:
        try:
            ip = ipaddress.ip_address(ip_str)
        except ValueError:
            report["invalid_entries"].append({
                "ip": ip_str,
                "network": network_str,
                "error": "Invalid IP Address"
            })
            continue

        try:
            network = ipaddress.ip_network(network_str, strict=False)
        except ValueError:
            report["invalid_entries"].append({
                "ip": ip_str,
                "network": network_str,
                "error": "Invalid Network"
            })
            continue

        contains = ip in network
        report["valid_pairs"].append({
            "ip": ip_str,
            "network": network_str,
            "contains": contains
        })

        if network_str not in report["network_sizes"]:
            report["network_sizes"][network_str] = network.num_addresses

    return report

def count_characters(input_string):
    """
    Returns a dictionary with the count of each character in the input string,
    ignoring case sensitivity and excluding whitespace characters.
    """
    counts = {}
    input_string = input_string.replace(" ", "").lower()

    for char in input_string:
        if char in counts:
            counts[char] += 1
        else:
            counts[char] = 1

    return counts

def fibonacci(n):
    """
    Returns the Fibonacci sequence up to the n-th term.
    """
    if n <= 0:
        return []
    elif n == 1:
        return [0]
    elif n == 2:
        return [0, 1]

    fib_sequence = [0, 1]
    for _ in range(2, n):
        next_term = fib_sequence[-1] + fib_sequence[-2]
        fib_sequence.append(next_term)

    return fib_sequence

import os
import time


def most_recently_modified_file(directory_path):
    """
    Returns the most recently modified file in a directory path and its last modification timestamp.
    If the directory is empty or does not exist, return None.

    :param directory_path: Path to the directory
    :return: Tuple containing the filename and its last modification time, or None
    """
    try:
        # List all files in the directory with their modification times
        files_mod_times = [
            (f, os.path.getmtime(os.path.join(directory_path, f)))
            for f in os.listdir(directory_path)
            if os.path.isfile(os.path.join(directory_path, f))
        ]

        if not files_mod_times:
            return None

        # Find the file with the maximum modification time
        most_recent_file = max(files_mod_times, key=lambda x: x[1])

        filename, timestamp = most_recent_file
        return filename, time.ctime(timestamp)

    except FileNotFoundError:
        return None

def are_collinear(points):
    if len(points) < 2:
        return True  # fewer than 2 points are collinear by definition

    # choose the first point
    x0, y0 = points[0]

    # calculate slope of line segment joining first point to all other points
    slope_to_first = None
    for x, y in points[1:]:
        if x == x0:
            slope = float('inf')
        else:
            slope = (y - y0) / (x - x0)

        if slope_to_first is None:
            slope_to_first = slope
        elif slope != slope_to_first:
            return False

    return True
